#include "CymbalSurface.h"
namespace cymbalforge { CymbalSurface::CymbalSurface(CymbalEngine& e):engine(e) {} void CymbalSurface::paint(juce::Graphics& g) { auto r=getLocalBounds().toFloat().reduced(12); auto c=r.getCentre(); auto radius=juce::jmin(r.getWidth(),r.getHeight())/2; g.fillAll(juce::Colour(0xff101217)); g.setColour(juce::Colour(0xffd2ad57)); g.fillEllipse(c.x-radius,c.y-radius,radius*2,radius*2); g.setColour(juce::Colour(0xff715829)); for(float f:{.2f,.48f,.76f}) g.drawEllipse(c.x-radius*f,c.y-radius*f,radius*f*2,radius*f*2,2); g.setColour(juce::Colours::white.withAlpha(.75f)); g.drawFittedText("BELL     BOW     EDGE",getLocalBounds(),juce::Justification::centredBottom,1); } void CymbalSurface::mouseDown(const juce::MouseEvent& e) { auto c=getLocalBounds().getCentre().toFloat(); auto d=e.position.getDistanceFrom(c)/(juce::jmin(getWidth(),getHeight())*.5f); auto position=juce::jlimit(0.0f,1.0f,d); engine.parameters.position=position; engine.strike(engine.parameters.velocity.load(),position); repaint(); } }
